<template>
  <section class="food-card" aria-label="外卖红黑榜">
    <header><span class="food-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M3 9h18M5 9v11h14V9M2 9l3-6h14l3 6M9 20v-6h6v6"/></svg></span><div><small>同学餐饮经验库</small><h4>外卖红黑榜</h4></div><span class="food-total">{{ counts.all }} 条记录</span></header>
    <p class="food-notice">保留同学原评价，红榜也可能有缺点。评价有分歧单列展示，实际营业、价格与配送请向商家确认。</p>
    <div class="food-tabs" role="group" aria-label="评价分类"><button v-for="tab in tabs" :key="tab.value" type="button" :class="{active:verdict===tab.value}" :aria-pressed="verdict===tab.value" :disabled="disabled" @click="verdict=tab.value">{{ tab.label }} <span>{{ counts[tab.key] }}</span></button></div>
    <div class="food-filters"><input v-model="q" type="search" aria-label="搜索商家与评价" placeholder="搜索商家、菜品或评价" :disabled="disabled"/><select v-model="category" aria-label="餐饮类别" :disabled="disabled"><option value="">全部类别</option><option v-for="c in categories" :key="c">{{ c }}</option></select><select v-model="place" aria-label="餐饮位置" :disabled="disabled"><option value="">全部位置</option><option v-for="p in places" :key="p">{{ p }}</option></select></div>
    <div class="food-status" aria-live="polite"><span>{{ loading?'正在读取榜单…':`匹配 ${total} 条` }}</span><button type="button" :disabled="disabled" @click="$emit('ask','今天吃什么')">帮我选一餐 ↗</button></div>
    <div v-if="error" role="alert" class="food-empty">榜单暂时加载失败 <button type="button" :disabled="disabled || loading" @click="load">重新读取</button></div>
    <div v-else-if="!loading && !items.length" class="food-empty">{{ enabled?'没有匹配记录，试试其他条件。':'这份餐饮知识库尚未启用。' }}</div>
    <div class="food-grid" :aria-busy="loading"><article v-for="item in items" :key="item.id" :data-campus-entry="'food:'+item.id" data-campus-collection="takeout"><div class="food-item-heading"><strong>{{ item.name }}</strong><span class="food-verdict" :class="item.verdict">{{ labels[item.verdict] }}</span></div><div class="food-tags"><span>{{ item.category }}</span><span>{{ item.pgroup }}</span><span v-if="item.price">价格记录：{{ item.price }}</span></div><p v-if="item.place" class="food-place">{{ item.place }}</p><details @toggle="track($event,item)"><summary>{{ item.reviews.length }} 条同学评价 · 展开查看</summary><ul><li v-for="(review,i) in item.reviews" :key="i">{{ review }}</li></ul><small v-if="item.sources.length">原始资料：{{ item.sources.join('、') }}</small></details></article></div>
    <nav v-if="total>20" aria-label="榜单翻页"><button type="button" :disabled="disabled || loading || page<=1" @click="page--">上一页</button><span>{{ page }} / {{ Math.ceil(total/20) }}</span><button type="button" :disabled="disabled || loading || page>=Math.ceil(total/20)" @click="page++">下一页</button></nav>
  </section>
</template>
<script setup lang="ts">
import {ref,watch,onBeforeUnmount} from 'vue'
import {trackCampus} from '@/utils/campus-activity'
interface Item {id:number;name:string;price:string;place:string;pgroup:string;category:string;verdict:'good'|'mixed'|'bad';reviews:string[];sources:string[]}
const props=defineProps<{card:Record<string,unknown>;disabled?:boolean}>()
defineEmits<{(e:'ask',q:string):void}>()
const verdict=ref(['good','mixed','bad'].includes(String(props.card.verdict))?String(props.card.verdict):''),q=ref(''),category=ref(''),place=ref(''),page=ref(1),loading=ref(false),error=ref(false),enabled=ref(true),items=ref<Item[]>([]),categories=ref<string[]>([]),places=ref<string[]>([]),total=ref(0),counts=ref({all:0,good:0,mixed:0,bad:0})
const labels={good:'红榜',mixed:'评价有分歧',bad:'黑榜'},tabs=[{value:'',label:'全部',key:'all'},{value:'good',label:'红榜',key:'good'},{value:'mixed',label:'有分歧',key:'mixed'},{value:'bad',label:'黑榜',key:'bad'}] as const
let timer:ReturnType<typeof setTimeout>|undefined,abort:AbortController|undefined,sequence=0
async function load(){abort?.abort();abort=new AbortController();const current=++sequence;loading.value=true;error.value=false
 try{const params=new URLSearchParams({q:q.value,verdict:verdict.value,category:category.value,place:place.value,page:String(page.value)}),response=await fetch((import.meta.env.VITE_API_BASE||'/api')+'/campus/food?'+params,{signal:abort.signal}),json=await response.json();if(!response.ok||json.code!==0||!Array.isArray(json.data?.items))throw Error('Invalid catalog');if(current!==sequence)return;const data=json.data;items.value=data.items;total.value=data.total;counts.value=data.counts;categories.value=data.categories;places.value=data.places;enabled.value=data.enabled
 }catch(e){if(current===sequence&&(e as Error).name!=='AbortError'){error.value=true;items.value=[]}}finally{if(current===sequence)loading.value=false}}
watch([q,verdict,category,place],()=>{page.value=1;clearTimeout(timer);timer=setTimeout(load,180)})
watch(page,()=>{clearTimeout(timer);timer=setTimeout(load,0)})
function track(event:Event,item:Item){if((event.target as HTMLDetailsElement).open)trackCampus('CONTENT_VIEW',{entryId:'food:'+item.id,collection:'takeout',title:item.name})}
void load();onBeforeUnmount(()=>{sequence++;clearTimeout(timer);abort?.abort()})
</script>
<style scoped>
.food-card{padding:22px;border:1px solid var(--nx-border,var(--el-border-color));border-radius:20px;background:var(--nx-surface,var(--el-bg-color));color:var(--nx-text,var(--el-text-color-primary));margin:16px 0}.food-card header{display:flex;gap:12px;align-items:center}.food-icon{display:grid;place-items:center;width:44px;height:44px;border-radius:14px;background:var(--nx-accent-soft,var(--el-color-primary-light-9));color:var(--nx-accent,var(--el-color-primary));flex-shrink:0}.food-icon svg{width:26px;height:26px}.food-card h4{margin:4px 0 0;font-size:20px}.food-card small,.food-total,.food-place{color:var(--nx-text-2,var(--el-text-color-secondary));font-size:11px}.food-total{margin-left:auto;white-space:nowrap}.food-notice{font-size:12px;line-height:1.8;color:var(--nx-text-2,var(--el-text-color-secondary));margin:16px 0}.food-tabs{display:flex;gap:7px;flex-wrap:wrap}.food-card button,.food-card input,.food-card select{font:inherit;font-size:12px;color:inherit;border:1px solid var(--nx-border,var(--el-border-color));background:var(--nx-surface-2,var(--el-fill-color-light));border-radius:10px;padding:9px 11px}.food-card button{cursor:pointer}.food-tabs button.active{background:var(--nx-accent-soft,var(--el-color-primary-light-9));border-color:var(--nx-accent,var(--el-color-primary));color:var(--nx-accent,var(--el-color-primary))}.food-tabs span{margin-left:5px;font-size:10px}.food-filters{display:grid;grid-template-columns:minmax(100px,1fr) minmax(90px,.6fr) minmax(90px,.7fr);gap:8px;margin-top:14px}.food-filters>*{min-width:0}.food-status{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:11px;color:var(--nx-text-2,var(--el-text-color-secondary));margin:12px 0}.food-status button{color:var(--nx-accent,var(--el-color-primary));background:transparent;border:0}.food-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.food-grid[aria-busy=true]{opacity:.55}.food-grid article{padding:15px;border:1px solid var(--nx-border,var(--el-border-color));border-radius:14px;min-width:0;background:var(--nx-surface-2,var(--el-fill-color-light))}.food-item-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:8px}.food-item-heading strong{font-size:14px;line-height:1.6;overflow-wrap:anywhere}.food-verdict{font-size:10px;padding:3px 7px;border-radius:6px;white-space:nowrap}.good{color:var(--el-color-success);background:var(--el-color-success-light-9)}.mixed{color:var(--el-color-warning);background:var(--el-color-warning-light-9)}.bad{color:var(--el-color-danger);background:var(--el-color-danger-light-9)}.food-tags{display:flex;gap:5px;flex-wrap:wrap;margin:9px 0;font-size:10px;color:var(--nx-text-2,var(--el-text-color-secondary))}.food-tags span{border:1px solid var(--nx-border,var(--el-border-color));border-radius:5px;padding:3px 5px}.food-card summary{cursor:pointer;font-size:11px;line-height:1.7;color:var(--nx-accent,var(--el-color-primary))}.food-card ul{padding-left:18px;margin:10px 0}.food-card li{font-size:12px;line-height:1.8;margin:6px 0;overflow-wrap:anywhere}.food-card nav{display:flex;justify-content:center;gap:12px;align-items:center;margin-top:18px;font-size:12px}.food-empty{padding:24px;text-align:center;font-size:12px}.food-card button:disabled{opacity:.5;cursor:default}.food-card :is(button,input,select,summary):focus-visible{outline:2px solid var(--nx-accent,var(--el-color-primary));outline-offset:3px}@media(max-width:560px){.food-card{padding:16px 12px}.food-grid{grid-template-columns:1fr}.food-filters{grid-template-columns:repeat(2,minmax(0,1fr))}.food-filters input{grid-column:span 2}.food-card h4{font-size:18px}}
</style>
